<?php get_header(); ?><main class="section"><div class="eyebrow">МУЗЫКА ХИТ</div><h1>Все песни</h1><div class="chart"><?php $songs=new WP_Query(['post_type'=>'orh_song','posts_per_page'=>-1,'post_status'=>'publish','meta_key'=>'orh_plays','orderby'=>'meta_value_num date','order'=>'DESC']); if($songs->have_posts()):$rank=0;while($songs->have_posts()):$songs->the_post();$aid=(int)get_post_meta(get_the_ID(),'orh_artist_id',true);$an=$aid?get_the_title($aid):'Артист';$au=orh_song_audio(get_the_ID());$thumb=orh_media_url(get_the_ID(),'thumbnail');$plays=(int)get_post_meta(get_the_ID(),'orh_plays',true);?><div class="row"><span class="rank">#<?php echo ++$rank;?></span><button class="mini-cover" type="button" aria-label="Слушать <?php echo esc_attr(get_the_title());?>" onclick="playSong(<?php echo esc_attr(get_the_ID());?>,'<?php echo esc_js(get_the_title());?>','<?php echo esc_js($an);?>','<?php echo esc_url($au);?>','<?php echo esc_url($thumb);?>')"><?php if($thumb):?><img src="<?php echo esc_url($thumb);?>" alt="" loading="lazy"><?php else:?><span>♪</span><?php endif;?></button><div class="name"><b><?php the_title();?></b><small><?php echo esc_html($an);?></small><small><?php echo esc_html(number_format_i18n($plays));?> прослушиваний</small></div><span></span><button type="button" aria-label="Включить <?php echo esc_attr(get_the_title());?>" onclick="playSong(<?php echo esc_attr(get_the_ID());?>,'<?php echo esc_js(get_the_title());?>','<?php echo esc_js($an);?>','<?php echo esc_url($au);?>','<?php echo esc_url($thumb);?>')"><span class="mini-play-icon" aria-hidden="true"></span></button></div><?php endwhile;wp_reset_postdata();else:?><div class="empty">Песни пока не опубликованы.</div><?php endif;?></div></main><?php get_footer();?>